// ============================================================================
// src/lib/tools/vlan-tag-and-trunk-calculator/golden-vectors.ts
// ----------------------------------------------------------------------------
// GOLDEN VECTORS for the 802.1Q tag decoder and trunk VLAN calculator.
//
// Every expected value in COMPUTED below was derived on 2026-11-08 by a
// separate Python oracle (work/oracle.py in the build's work folder), not by
// running this engine: its own hexadecimal parser and bit arithmetic for the
// tags, its own reading of IANA's Ethertypes XML (the narrowest row wins),
// P802.1ad/D2.4 Tables 6-5 and G-2 retyped by PCP, and, for the trunks, its
// own parser per vendor and Python sets for the VLAN arithmetic. The table was
// written from the oracle's output by work/gen_vectors.py, so no expected
// value was typed by hand; a cross-check of every oracle field against the
// engine (work/crosscheck.mts: 71 inputs, 1,687 fields) found no difference.
// 2026-11-08b (set ...-2026-11-08b): Arista EOS 4.37.0F and Huawei VRP
// V200R025C00 added from pages read in a browser (their sites refuse
// automated reads); a native VLAN left out of the AOS-CX allowed list is
// now not carried (HPE Aruba's 10.16 example), where it was not confirmed;
// the lab lines follow the corrected deck (999 in each allowed list). A
// second pass the same evening (more browser reads) accepts Arista's no and
// default native forms and Huawei's undo port trunk pvid vlan, marks an
// allowed native VLAN under Arista's native vlan tag not confirmed, and
// quotes why only-vlan does not apply to a static trunk.
// The page's Examples and chips (examples.ts: the VLAN lab of chapter 2.3 of
// the course, and RFC 9542's documentation MAC addresses) are vectors here,
// and verifyVectors checks that each one is. The refusals and the sentences
// that carry the rules are written out at the end, each with the rule it pins.
// GOLDEN_VECTOR_SET_ID changes whenever a vector changes (the api-sync rule).
// ============================================================================

import { run, runApi, type VlanRequest, type VlanResult } from "./compute"; // the engine's API entries
import { EXAMPLE_TAG_REQUEST, TAG_CHIPS, EXAMPLE_TRUNK_REQUEST, TRUNK_CHIPS } from "./examples"; // the page's Examples and chips, pinned below

/** The set id: dated, changed with any vector (scripts/check-api-sync.mjs compares it with scripts/api-sync.json). */
export const GOLDEN_VECTOR_SET_ID = "vlan-tag-and-trunk-calculator-golden-2026-11-08b"; // 2026-11-08b: Arista EOS, Huawei VRP, AOS-CX native left out; the first set was ...-2026-11-08

/** A text a reading's sentence must contain, at a dotted path ("warnings", "a.notes", "tags.0.notes", "next.text", "verdict"). */
export interface Contains {
  /** Where: a string, or an array of strings, in the reading. */
  path: string;
  /** The text one of them must contain. */
  text: string;
}

/** One vector: a request (or raw API text), and either the fields expected or the error expected. */
export interface VlanVector {
  /** A stable id. */
  id: string;
  /** Where the expected values come from. */
  note: string;
  /** The request object (run()). */
  request?: VlanRequest;
  /** Or the raw API body (runApi()). */
  api?: string;
  /** The fields expected (a subset of the reading; objects compared as subsets, arrays element by element). */
  expect?: Record<string, unknown>;
  /** Texts the reading's sentences must contain. */
  contains?: Contains[];
  /** The error expected, as a pattern over its message. */
  expectError?: RegExp;
}

/** The page's Examples and chips, re-exported by the conventional names. */
export { EXAMPLE_TAG_REQUEST, TAG_CHIPS, EXAMPLE_TRUNK_REQUEST, TRUNK_CHIPS }; // the Examples

/** The tag chip of an id (the vectors pin each chip by its id). */
const tagChip = (id: string): string => TAG_CHIPS.find((c) => c.id === id)?.input ?? ""; // its octets
/** The trunk chip of an id. */
const trunkChip = (id: string) => TRUNK_CHIPS.find((c) => c.id === id); // its ends

