/** Every vector, in order. */
export const VLAN_VECTORS: readonly VlanVector[] = Object.freeze([...COMPUTED, ...WRITTEN]); // the table first, then the rest

/**
 * Whether `actual` holds `expected`: objects as subsets, arrays of the same length element by element, anything else
 * exactly as JSON.
 * @param actual the reading's value
 * @param expected the vector's value
 * @returns true when it matches
 */
function matches(actual: unknown, expected: unknown): boolean {
  if (Array.isArray(expected)) { // a list
    if (!Array.isArray(actual) || actual.length !== expected.length) return false; // the same length
    return expected.every((e, i) => matches(actual[i], e)); // each element
  } // array
  if (expected !== null && typeof expected === "object") { // a subset object
    if (actual === null || typeof actual !== "object") return false; // nothing to compare with
    return Object.entries(expected as Record<string, unknown>).every(([k, v]) => matches((actual as Record<string, unknown>)[k], v)); // each field
  } // object
  return JSON.stringify(actual) === JSON.stringify(expected); // exact, as JSON
} // matches

/**
 * The strings at a dotted path of a reading.
 * @param r the reading
 * @param path "warnings", "a.notes", "tags.0.notes", "next.text" ...
 * @returns the strings found there
 */
function stringsAt(r: unknown, path: string): string[] {
  let v: unknown = r; // the walk
  for (const k of path.split(".")) v = v !== null && typeof v === "object" ? (v as Record<string, unknown>)[k] : undefined; // one step
  if (typeof v === "string") return [v]; // one string
  if (Array.isArray(v)) return v.filter((x): x is string => typeof x === "string"); // a list of strings
  return []; // nothing
} // stringsAt

/** The report verifyVectors returns. */
export interface VerifyReport {
  /** The set id. */
  setId: string;
  /** Vectors run. */
  total: number;
  /** Vectors that passed. */
  passed: number;
  /** One line per failure (empty when all pass). */
  failures: string[];
}

/**
 * Run every vector, and check that each Example and chip of the page is one of them.
 * @returns the report (failures empty when all pass)
 */
export function verifyVectors(): VerifyReport {
  const failures: string[] = []; // collected
  for (const v of VLAN_VECTORS) { // each vector
    let r: VlanResult | null = null; // the reading
    try {
      r = v.api !== undefined ? runApi(v.api) : run(v.request as VlanRequest); // the API text or the request
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e); // the refusal
      if (!v.expectError) failures.push(`${v.id}: unexpected error: ${msg}`); // should have computed
      else if (!v.expectError.test(msg)) failures.push(`${v.id}: error mismatch: ${msg}`); // the wrong refusal
      continue; // next vector
    } // ran
    if (v.expectError) { failures.push(`${v.id}: expected an error, got a reading`); continue; } // should have refused
    if (v.expect && !matches(r, v.expect)) failures.push(`${v.id}: fields differ: ${JSON.stringify(r).slice(0, 400)}`); // a value moved
    for (const c of v.contains ?? []) if (!stringsAt(r, c.path).some((s) => s.includes(c.text))) failures.push(`${v.id}: nothing at ${c.path} contains "${c.text}"`); // a sentence
  } // vectors
  // D-83: every Example and chip the page offers is a computed vector.
  if (!VLAN_VECTORS.some((v) => v.request === EXAMPLE_TAG_REQUEST && v.expect)) failures.push("example-tag: the tag Example is not a computed vector"); // tag Example
  if (!VLAN_VECTORS.some((v) => v.request === EXAMPLE_TRUNK_REQUEST && v.expect)) failures.push("example-trunk: the trunk Example is not a computed vector"); // trunk Example
  for (const c of TAG_CHIPS) if (!VLAN_VECTORS.some((v) => v.expect && (v.request as { input?: string } | undefined)?.input === c.input)) failures.push(`chip-tag-${c.id}: not a computed vector`); // tag chips
  for (const c of TRUNK_CHIPS) if (!VLAN_VECTORS.some((v) => v.expect && (v.request as { a?: unknown } | undefined)?.a === c.a)) failures.push(`chip-trunk-${c.id}: not a computed vector`); // trunk chips
  return { setId: GOLDEN_VECTOR_SET_ID, total: VLAN_VECTORS.length, passed: VLAN_VECTORS.length - new Set(failures.map((f) => f.split(":")[0])).size, failures }; // the report
} // verifyVectors
